query:
SELECT id, enterpriseName, industry, status, website, productIntro, targetCustomers, coreSellingPoints, competitorNames, coreKeywords FROM projects WHERE enterpriseName = '海豚知道';
SELECT COUNT(*) AS question_count, SUM(CASE WHEN source IN ('manual','csv') OR questionType='指定问题' THEN 1 ELSE 0 END) AS specified_question_count FROM questions WHERE projectId = (SELECT id FROM projects WHERE enterpriseName='海豚知道' LIMIT 1);
SELECT id, questionText, questionType, source, businessValue FROM questions WHERE projectId = (SELECT id FROM projects WHERE enterpriseName='海豚知道' LIMIT 1) AND (source IN ('manual','csv') OR questionType='指定问题') ORDER BY id LIMIT 12;
SELECT COUNT(*) AS analysis_count, SUM(CASE WHEN manually_reviewed=1 THEN 1 ELSE 0 END) AS reviewed_count FROM analysis_results WHERE projectId = (SELECT id FROM projects WHERE enterpriseName='海豚知道' LIMIT 1);
SELECT ar.id, ar.notRecommendedReason, ar.contentGap, ar.optimizationSuggestion, ar.recommendedCompetitors, ar.manually_reviewed FROM analysis_results ar WHERE ar.projectId = (SELECT id FROM projects WHERE enterpriseName='海豚知道' LIMIT 1) ORDER BY ar.manually_reviewed DESC, ar.id LIMIT 8;
SELECT id, taskName, taskType, priority, status, need_retest, published_url FROM optimization_tasks WHERE projectId = (SELECT id FROM projects WHERE enterpriseName='海豚知道' LIMIT 1) ORDER BY FIELD(priority,'P0','P1','P2'), id LIMIT 10;
SELECT COUNT(*) AS article_count FROM geo_articles WHERE projectId = (SELECT id FROM projects WHERE enterpriseName='海豚知道' LIMIT 1);
SELECT COUNT(*) AS publication_count FROM geo_publish_records WHERE projectId = (SELECT id FROM projects WHERE enterpriseName='海豚知道' LIMIT 1);

